package dev.tempest.gui;

import dev.tempest.module.Category;
import net.minecraft.client.gl.RenderPipelines;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.util.Identifier;

import java.util.HashMap;
import java.util.Map;

/**
 * White line icons from textures/gui/icons.png (generated by tools/make_icons.py, 64px cells, 8 per row).
 * Icons are tinted when drawn, so one atlas serves every colour.
 */
public final class Icons {
    private static final Identifier ATLAS = Identifier.of("tempest", "textures/gui/icons.png");
    private static final int CELL = 64, COLS = 8;
    /** Same order as GLYPHS in tools/make_icons.py. */
    private static final String[] NAMES = {"star_outline", "star_filled", "gear", "person", "people", "grid", "power", "globe", "arrow_circle", "runner", "shirt", "search", "gauge", "mouse", "keyboard", "ruler", "bolt", "heart", "potion", "apple", "chestplate", "hourglass", "shield", "pin", "signal", "backpack", "clock", "list", "board", "totem", "chat", "crystal", "bell", "cube", "person_plus", "magnifier", "crosshair", "sun", "eye", "idcard", "cape", "film_camera", "box", "moon", "sun_moon", "outline_square", "motion", "xray", "lock", "refresh", "swap", "info", "camera", "broadcast", "servers", "flame", "hotbar", "sparkles", "fov", "orbs", "layers", "at", "stack", "planet_stars", "galaxy", "cloud", "aurora", "black_hole", "ringed_planet", "shooting_star", "fireflies", "aperture", "palette", "layout", "compass", "play", "plus", "trash", "back", "pencil", "wings", "halo", "horns", "crown", "cat_ears", "bunny", "antlers", "flower", "witch_hat", "top_hat", "snowflake", "note", "emote_wave", "emote_clap", "emote_dance", "emote_dab", "emote_salute", "emote_facepalm", "emote_cheer", "emote_shrug", "bucket", "eyedropper", "eraser", "undo", "redo", "brush"};
    private static final int ATLAS_W = COLS * CELL, ATLAS_H = ((NAMES.length + COLS - 1) / COLS) * CELL;

    private static final Map<String, Integer> INDEX = new HashMap<>();
    private static final Map<String, String> MODULES = new HashMap<>();

    static {
        for (int i = 0; i < NAMES.length; i++) INDEX.put(NAMES[i], i);
        String[][] m = {
                {"fps", "gauge"}, {"cps", "mouse"}, {"keystrokes", "keyboard"}, {"reach", "ruler"},
                {"combo", "bolt"}, {"target_health", "heart"}, {"potions", "potion"}, {"appleskin", "apple"},
                {"armor_hud", "chestplate"}, {"cooldowns", "hourglass"}, {"shield_status", "shield"},
                {"coordinates", "compass"}, {"server_address", "servers"}, {"pack_display", "layers"}, {"old_animations", "runner"}, {"kill_effects", "sparkles"}, {"chat_tabs", "chat"}, {"chat_animation", "motion"}, {"ping", "signal"}, {"inventory_hud", "grid"}, {"session", "clock"},
                {"info_bar", "list"}, {"scoreboard", "board"}, {"totem_pops", "totem"}, {"auto_gg", "chat"}, {"chat_macros", "chat"}, {"tier_tagger", "star_filled"}, {"discord", "people"},
                {"shield_fixes", "shield"}, {"low_shields", "shield"}, {"client_crystals", "crystal"}, {"alerts", "bell"}, {"hitboxes", "outline_square"},
                {"totem_tweaks", "totem"}, {"friends", "people"}, {"middle_click_friend", "person_plus"},
                {"zoom", "magnifier"}, {"fullbright", "sun"}, {"freelook", "eye"},
                {"who_am_i", "idcard"}, {"capes", "cape"}, {"cinematic", "film_camera"}, {"waypoints", "pin"},
                {"item_physics", "box"}, {"time_changer", "sun_moon"}, {"block_outline", "cube"}, {"motion_blur", "motion"},
                {"xray", "xray"}, {"anti_leak", "lock"}, {"mouse_tweaks", "mouse"}, {"shulker_preview", "backpack"},
                {"toggle_sprint", "runner"}, {"reconnect", "refresh"}, {"armor_swap", "swap"}, {"tooltip_info", "info"},
                {"screenshot_tools", "camera"}, {"streamer_mode", "broadcast"}, {"quick_servers", "servers"},
                {"low_fire", "flame"}, {"smooth_hotbar", "hotbar"}, {"particle_filter", "sparkles"}, {"custom_fov", "fov"},
                {"fast_screens", "layout"}, {"clumps", "orbs"}, {"nametags", "idcard"}, {"chat_mentions", "at"},
                {"message_stacking", "stack"}, {"chat_upgrades", "chat"}, {"client", "gear"},
                {"custom_sky", "planet_stars"}, {"cosmetics", "wings"}, {"emotes", "emote_wave"}, {"fake_chunks", "cube"}, {"spotify", "note"}, {"texture_painter", "brush"}, {"fireflies", "fireflies"}, {"cinematic_grade", "aperture"},
        };
        for (String[] e : m) MODULES.put(e[0], e[1]);
    }

    private Icons() { }

    public static boolean has(String name) { return INDEX.containsKey(name); }

    /** Icon name for a module id (falls back to a generic grid). */
    public static String forModule(String id) { return MODULES.getOrDefault(id, "grid"); }

    /** Icon name for a sidebar category; null = "All Mods". */
    public static String forCategory(Category c) {
        if (c == null) return "grid";
        return switch (c) {
            case HUD -> "layout";
            case PVP -> "shield";
            case RENDER -> "eye";
            case VISUALS -> "planet_stars";
            case QOL -> "sparkles";
            case UTILITY -> "gear";
            case CHAT -> "chat";
            case CLIENT -> "palette";
        };
    }

    /** Draws icon {@code name} as a {@code size} x {@code size} square at (x, y), tinted with ARGB {@code color}. */
    public static void draw(DrawContext ctx, String name, int x, int y, int size, int color) {
        if (size <= 0 || ((color >>> 24) & 255) == 0) return;
        Integer i = INDEX.get(name);
        if (i == null) i = INDEX.get("grid");
        int u = (i % COLS) * CELL, v = (i / COLS) * CELL;
        ctx.drawTexture(RenderPipelines.GUI_TEXTURED, ATLAS, x, y, (float) u, (float) v, size, size, CELL, CELL, ATLAS_W, ATLAS_H, color);
    }
}
